const getTechDetails = (tech, language = 'en') => {
  const techInfo = techDetails[tech.name];

  if (techInfo) {
    return {
      summary: techInfo.summary[language] || techInfo.summary.en || techInfo.summary.id,
      details: techInfo.details[language] || techInfo.details.en || techInfo.details.id,
    };
  }

  return {
    summary: language === 'id'
      ? `Informasi umum tentang ${tech.name}.`
      : `General information about ${tech.name}.`,
    details: language === 'id'
      ? `Teknologi ${tech.name} digunakan dalam pengembangan proyek sesuai fungsinya.`
      : `${tech.name} is used in project development according to its purpose.`,
  };
};

//Double tehcstack for infinite vertical animation
const doubleTech = [...techStack, ...techStack];
const Biodata = ({ language = 'en' }) => {

  //Mempersiapkan State untuk menyimpan kodisi layar
  const [isMobile, setIsMobile] = useState(false);
  const [isTechModalOpen, setIsTechModalOpen] = useState(false);
  const [selectedTech, setSelectedTech] = useState(null);

  useEffect(() => {
    //Function untuk cek lebar layar
    const checkWidth = () => {
      setIsMobile(window.innerWidth < 576);
    }
    checkWidth();
    window.addEventListener("resize", checkWidth);
    //Bersihkan event saat komponen tidak digunakan
    return () => window.removeEventListener("resize", checkWidth);
  }, []);

  const openTechModal = (tech) => {
    setSelectedTech(tech);
    setIsTechModalOpen(true);
  };

  const closeTechModal = () => {
    setIsTechModalOpen(false);
    setSelectedTech(null);
  };
  return (
    <section className="biodata-section fade-in-item" id="about">
      <SectionContainer>
        <div className="biodata-grid">
          <div className="biodata-side">
            <div className="biodata-intro card">
              <p className="section-label">{language === 'id' ? 'Tentang Saya' : 'About Me'}</p>
              <h2 className="section-title">{language === 'id' ? 'Ringkasan Profil' : 'Profile Summary'}</h2>
              <p className="section-copy">
                {language === 'id'
                  ? 'Berbekal pembelajaran mandiri, saya menggabungkan dasar-dasar coding dengan desain visual yang berdampak. Saya menerapkan prinsip keamanan siber untuk membangun ekosistem aplikasi yang aman, sekaligus memanfaatkan kemampuan organisasi sebagai operator sekolah.'
                  : 'Driven by self-directed learning, I bridge coding fundamentals with impactful visual design. I integrate cybersecurity essentials to build secure application ecosystems, while leveraging my structured organizational skills as a school operator.'}
              </p>
              <div className="biodata-tags">
                <span>Fullstack</span>
                <span>Designer</span>
                <span>School Operator</span>
                <span>School System</span>
              </div>
            </div>

            <div className="techstack-card card">
              <p className="section-label">Tech Stack</p>
              <h3 className="location-title">{language === 'id' ? 'Fundamental yang saya kuasai' : 'Fundamentals I know'}</h3>
              <div className="vertical-scroll-container">
                <div className="techstack-scroll">
                  <div className="techstack-grid">
                    {doubleTech.map((tech, index) => (
                      <div
                        className="techstack-item"
                        key={`${tech.name}-${index}`}
                        style={{ borderColor: tech.color }}
                        role="button"
                        tabIndex={0}
                        onClick={() => openTechModal(tech)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            openTechModal(tech);
                          }
                        }}
                      >
                        <span className="techstack-icon" style={{ background: tech.color }}>
                          <img src={tech.logo} alt={`${tech.name} logo`} width={tech.size ? tech.size : undefined} />
                        </span>
                        <span>{tech.name}</span>
                      </div>
                    ))}
                  </div>
                </div>
                <div className="techstack-scroll-reverse">
                  <div className="techstack-grid">
                    {isMobile && doubleTech.map((tech, index) => (
                      <div
                        className="techstack-item"
                        key={`${tech.name}-mobile-${index}`}
                        style={{ borderColor: tech.color }}
                        role="button"
                        tabIndex={0}
                        onClick={() => openTechModal(tech)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            openTechModal(tech);
                          }
                        }}
                      >
                        <span className="techstack-icon" style={{ background: tech.color }}>
                          <img src={tech.logo} alt={`${tech.name} logo`} width={tech.size ? tech.size : undefined} />
                        </span>
                        <span>{tech.name}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="biodata-cards">
            {personalInfo.map((item) => (
              <InfoCard
                key={item.title}
                {...item}
                title={language === 'id' ? item.titleId : item.title}
                description={language === 'id' ? (item.descriptionId || item.description) : (item.descriptionEn || item.description)}
              />
            ))}
          </div>
        </div>
      </SectionContainer>

      <Modal
        isOpen={isTechModalOpen}
        onClose={closeTechModal}
        title={selectedTech ? selectedTech.name : 'Tech Stack'}
        icon={selectedTech ? selectedTech.logo : null}
        color={selectedTech ? selectedTech.color : '#000'}
        size="md"
      >
        {selectedTech && (() => {
          const selectedTechDetails = getTechDetails(selectedTech, language);

          return (
            <>
              <p style={{ margin: 0, marginBottom: '1rem', fontWeight: '700' }}>
                {selectedTechDetails.summary}
              </p>
              <p style={{ margin: 0, whiteSpace: 'pre-line' }}>
                {selectedTechDetails.details}
              </p>
            </>
          );
        })()}
      </Modal>
    </section>
  );
};

export default Biodata;
